package com.automation.util;
import com.fasterxml.jackson.databind.*; import java.io.*; import java.util.*;
public final class JsonDataReader { private static final ObjectMapper M=new ObjectMapper(); private JsonDataReader(){} public static Object[][] getTestData(String file,String method){try(InputStream in=JsonDataReader.class.getClassLoader().getResourceAsStream(file)){if(in==null) throw new IllegalArgumentException("Test data file not found: "+file); JsonNode n=M.readTree(in).get(method); if(n==null||!n.isArray()) throw new IllegalArgumentException("No array data for test method: "+method); List<Object[]> out=new ArrayList<>(); for(JsonNode row:n) out.add(new Object[]{M.convertValue(row,Map.class)}); return out.toArray(new Object[0][]);}catch(IOException e){throw new RuntimeException("Unable to read test data",e);}} }